import{describe,it,expect}from"vitest";import{states,influences,domains,filterStates,filterInfluences,getStateInfluences,findStateById,getUniqueDomains,getUniqueRegions}from"../../frontend/cultural-footprint/cultural-footprint.js";const REQUIRED_STATE_FIELDS=["id","name","region","capital","summary","coords"],REQUIRED_INFLUENCE_FIELDS=["id","source","target","domain","title","strength","description"];describe("Cultural Footprint States Dataset Integrity",()=>{it("contains at least 20 states in the dataset",()=>{expect(states.length).toBeGreaterThanOrEqual(20)}),it("every state contains all required fields with non-empty values",()=>{states.forEach((e,t)=>{REQUIRED_STATE_FIELDS.forEach(n=>{expect(e,`State at index ${t} missing field ${n}`).toHaveProperty(n),"coords"===n?(expect(typeof e.coords.x).toBe("number"),expect(typeof e.coords.y).toBe("number"),expect(e.coords.x).toBeGreaterThanOrEqual(0),expect(e.coords.x).toBeLessThanOrEqual(900),expect(e.coords.y).toBeGreaterThanOrEqual(0),expect(e.coords.y).toBeLessThanOrEqual(600)):(expect(typeof e[n]).toBe("string"),expect(e[n].trim().length).toBeGreaterThan(0))})})}),it("all state IDs and coordinates are unique",()=>{const e=states.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length);const n=new Set(states.map(e=>`${e.coords.x},${e.coords.y}`));expect(n.size).toBe(states.length)})}),describe("Cultural Footprint Influences & Network Integrity",()=>{it("contains at least 35 influence links in the dataset",()=>{expect(influences.length).toBeGreaterThanOrEqual(35)}),it("every influence link contains all required fields with valid values",()=>{influences.forEach((e,t)=>{REQUIRED_INFLUENCE_FIELDS.forEach(n=>{expect(e,`Influence link at index ${t} missing field ${n}`).toHaveProperty(n),"strength"===n?(expect(typeof e.strength).toBe("number"),expect(e.strength).toBeGreaterThanOrEqual(1),expect(e.strength).toBeLessThanOrEqual(5)):(expect(typeof e[n]).toBe("string"),expect(e[n].trim().length).toBeGreaterThan(0))})})}),it("every influence link references valid existing state IDs for source and target",()=>{const e=new Set(states.map(e=>e.id));influences.forEach((t,n)=>{expect(e.has(t.source),`Link at index ${n} source "${t.source}" does not exist`).toBe(!0),expect(e.has(t.target),`Link at index ${n} target "${t.target}" does not exist`).toBe(!0),expect(t.source,`Link at index ${n} cannot have self-referential influence`).not.toBe(t.target)})}),it("covers all 8 core cultural domains",()=>{const e=new Set(influences.map(e=>e.domain));expect(e.size).toBe(8),domains.forEach(t=>{expect(e.has(t),`Domain ${t} has no influence links mapped`).toBe(!0)})})}),describe("Cultural Footprint Filtering & Search",()=>{it("returns all states when query and region are default",()=>{const e=filterStates(states);expect(e.length).toBe(states.length)}),it("filters states by search query (e.g. Bengal)",()=>{const e=filterStates(states,{search:"Bengal"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.name,e.capital,e.region,e.summary].some(e=>e&&e.toLowerCase().includes("bengal"));expect(t).toBe(!0)})}),it("filters states by region (e.g. South)",()=>{const e=filterStates(states,{region:"South"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.region.toLowerCase()).toBe("south")})}),it("filters influence links by domain (e.g. cuisine)",()=>{const e=filterInfluences(influences,{domain:"cuisine"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.domain).toBe("cuisine")})}),it("filters influence links by origin state (e.g. WB)",()=>{const e=filterInfluences(influences,{originState:"WB"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.source).toBe("WB")})}),it("handles invalid or empty inputs gracefully",()=>{expect(filterStates(null)).toEqual([]),expect(filterInfluences(null)).toEqual([])})}),describe("Cultural Footprint Traversal & Lookups",()=>{it("finds state by ID correctly",()=>{const e=findStateById("TN");expect(e).toBeDefined(),expect(e.name).toBe("Tamil Nadu")}),it("returns incoming and outgoing influences for a given state",()=>{const{outgoing:e,incoming:t}=getStateInfluences("WB",influences);expect(e.length).toBeGreaterThan(0),expect(t.length).toBeGreaterThanOrEqual(0),e.forEach(e=>expect(e.source).toBe("WB")),t.forEach(e=>expect(e.target).toBe("WB"))}),it("extracts unique domains sorted alphabetically",()=>{const e=getUniqueDomains(influences);expect(e.length).toBe(8);for(let t=1;t<e.length;t++)expect(e[t-1].localeCompare(e[t])).toBeLessThanOrEqual(0)}),it("extracts unique regions",()=>{const e=getUniqueRegions(states);expect(e.length).toBeGreaterThan(0),expect(e).toContain("East"),expect(e).toContain("South"),expect(e).toContain("West"),expect(e).toContain("North")})});